// Generated by host_acceptance.py. Execute ONCE through Rhino MCP, then poll.
// No timer, waiting loop, private embedded-runtime fields, or source archive writes.
using Grasshopper.Kernel;
using Grasshopper.Kernel.Special;
using Grasshopper.Kernel.Parameters;
using Grasshopper.Kernel.Types;
using System.Text.Json.Nodes;
using System.IO;
using System.Security.Cryptography;
var s=JsonNode.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("__REQUEST_BASE64__"))).AsObject();
string output=s["output"].GetValue<string>(),phase=s["phase"].GetValue<string>(),run=s["run_id"].GetValue<string>();
int sequence=s["sequence"].GetValue<int>(),index=s["index"].GetValue<int>();
string replyPath=Path.Combine(output,$"reply-{sequence:D4}.json");
if(File.Exists(replyPath)){Console.WriteLine(File.ReadAllText(replyPath));return;}
// An uncertain in-flight request is never replayed: cancel via the control plane.
using(var claim=new FileStream(Path.Combine(output,$"request-{sequence:D4}.claim"),FileMode.CreateNew,FileAccess.Write)){}
var current=JsonNode.Parse(File.ReadAllText(Path.Combine(output,"state.json")));
if(current["run_id"].GetValue<string>()!=run || current["sequence"].GetValue<int>()!=sequence || current["status"].GetValue<string>()!="running")throw new Exception("Request superseded; refusing host action");
var r=new JsonObject{["run_id"]=run,["sequence"]=sequence,["phase"]=phase};
var doc=__rhino_doc__;
GH_Document owned=null;
try{
 if(doc!=Rhino.RhinoDoc.ActiveDoc)throw new Exception("MCP target must be the active dedicated Rhino document");
 if((long)doc.RuntimeSerialNumber!=s["rhino_serial"].GetValue<long>())throw new Exception("Rhino document changed");
 string ownedText=s["owned"]?.GetValue<string>();
 if(ownedText!=null){
  owned=AppDomain.CurrentDomain.GetData("HawaAcceptance:"+run) as GH_Document;
  if(owned!=null && owned.DocumentID!=Guid.Parse(ownedText))throw new Exception("Owned GH identity changed");
  if(owned!=null && owned.FilePath!=s["examples"][index].GetValue<string>())throw new Exception("Owned GH document path changed");
 }
 var shared=AppDomain.CurrentDomain.GetAssemblies().Single(a=>a.GetName().Name=="Hawa.Shared");
 var hub=shared.GetType("Hawa.Shared.CaseHub");
 int Pending()=>(int)hub.GetProperty("PendingCleanupCount").GetValue(null);
 var ghAssembly=AppDomain.CurrentDomain.GetAssemblies().Single(a=>a.GetName().Name=="Hawa.Grasshopper");
 int Refreshes()=>(int)ghAssembly.GetType("Hawa.Grasshopper.HawaPollScheduler").GetProperty("PendingCount").GetValue(null);
 if(phase=="preflight" || phase=="cleanup"){
  var audit=JsonNode.Parse(File.ReadAllText(Path.Combine(output,$"audit-{sequence:D4}.json"))).AsObject();
  if(audit["run_id"].GetValue<string>()!=run || audit["sequence"].GetValue<int>()!=sequence || audit["pid"].GetValue<int>()!=System.Diagnostics.Process.GetCurrentProcess().Id)throw new Exception("Missing or wrong-process runtime audit");
  if((DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000.0-audit["time"].GetValue<double>())>30)throw new Exception("Runtime audit older than 30 seconds");
  r["audit"]=JsonNode.Parse(audit.ToJsonString());r["pending_cleanup"]=Pending();r["pending_refreshes"]=Refreshes();
  bool idle=audit["jobs"].GetValue<int>()==0 && audit["sessions"].GetValue<int>()==0 && audit["workers"].AsArray().Count==0 && Pending()==0 && Refreshes()==0;
  foreach(var source in s["source_hashes"].AsObject()){
   var hash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(source.Key))).ToLowerInvariant();
   if(hash!=source.Value.GetValue<string>())throw new Exception("Source archive changed: "+source.Key);
  }
  if(phase=="preflight"){
   bool empty=!doc.Objects.Any(o=>!o.IsDeleted) && string.IsNullOrEmpty(doc.Path) && doc.ModelUnitSystem==Rhino.UnitSystem.Meters;
   bool casesIdle=true;
   foreach(dynamic c in (System.Collections.IEnumerable)hub.GetProperty("All").GetValue(null))
    if(c.Session!=null || c.Job!=null || c.State=="preparing" || c.State=="running")casesIdle=false;
   r["safe"]=idle && empty && casesIdle && hub.GetMethod("Find").Invoke(null,new object[]{doc.RuntimeSerialNumber})==null;
   r["rhino_serial"]=(long)doc.RuntimeSerialNumber;r["modified"]=doc.Modified;
   r["original_gh"]=Grasshopper.Instances.ActiveCanvas.Document?.DocumentID.ToString();
   r["rhino"]=Rhino.RhinoApp.Version.ToString();
   var hashes=new JsonObject();
   foreach(var a in new[]{shared,ghAssembly})hashes[a.GetName().Name]=new JsonObject{["path"]=a.Location,["sha256"]=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(a.Location)))};
   r["installed_files"]=hashes;
  }else{
   r["clean"]=idle && owned==null && !Grasshopper.Instances.DocumentServer.AllDocuments.Any(d=>d.FilePath==s["examples"][index].GetValue<string>());
   if(r["clean"].GetValue<bool>()){
    File.Delete(Path.Combine(output,"ownership.json"));
    var original=s["original_gh"]?.GetValue<string>();
    if(Grasshopper.Instances.ActiveCanvas.Document==null)
     Grasshopper.Instances.ActiveCanvas.Document=original==null?null:Grasshopper.Instances.DocumentServer.AllDocuments.SingleOrDefault(d=>d.DocumentID==Guid.Parse(original));
   }
  }
 }else if(phase=="open"){
  if(owned!=null)throw new Exception("Already owns a document");
  string path=s["examples"][index].GetValue<string>();
  var io=new GH_DocumentIO();if(!io.Open(path))throw new Exception("Cannot open copied definition");
  owned=io.Document;r["owned"]=owned.DocumentID.ToString();
  AppDomain.CurrentDomain.SetData("HawaAcceptance:"+run,owned);
  // Persist ownership before adding/solving, so a lost MCP reply can still cancel.
  File.WriteAllText(Path.Combine(output,"ownership.json"),new JsonObject{["run_id"]=run,["owned"]=owned.DocumentID.ToString()}.ToJsonString());
  if(owned.Objects.OfType<GH_BooleanToggle>().Any(t=>t.Value))throw new Exception("Copied definition must start idle");
  // Override only unconnected device values on this owned copy; never rewire.
  var devices=owned.Objects.OfType<GH_Component>().SelectMany(c=>c.Params.Input).Where(p=>p.Name=="Device").ToArray();
  if(devices.Length==0 || devices.Any(p=>p.Sources.Count!=0 || !(p is Param_String)))throw new Exception("Pilot requires direct device inputs");
  foreach(Param_String device in devices){device.PersistentData.Clear();device.SetPersistentData("cpu");}
  owned.FilePath=path;owned.AssociateWithRhinoDocument();Grasshopper.Instances.DocumentServer.AddDocument(owned);
  if(!Grasshopper.Instances.DocumentServer.Any(d=>ReferenceEquals(d,owned)))throw new Exception("Scratch document is excluded by Grasshopper active-document filter; activate its native window before retrying");
  Grasshopper.Instances.ActiveCanvas.Document=owned;owned.NewSolution(false);
 }else{
  if(owned==null && phase!="close")throw new Exception("Owned document disappeared");
  if(phase=="close"){
   if(owned!=null){
    foreach(var t in owned.Objects.OfType<GH_BooleanToggle>()){t.Value=false;t.ExpireSolution(false);}
    if(Grasshopper.Instances.ActiveCanvas.Document==owned)Grasshopper.Instances.ActiveCanvas.Document=null;
    Grasshopper.Instances.DocumentServer.RemoveDocument(owned);owned.Dispose();
    AppDomain.CurrentDomain.SetData("HawaAcceptance:"+run,null);
   }
  }else{
   if(Grasshopper.Instances.ActiveCanvas.Document!=owned)throw new Exception("User switched GH document; cancelling owned test");
   var components=owned.Objects.OfType<GH_Component>().ToArray();
   GH_Component C(string type)=>components.Single(c=>c.GetType().Name==type+"Component");
   void Toggle(string name){var t=owned.Objects.OfType<GH_BooleanToggle>().Single(t=>t.NickName==name);t.Value=true;t.ExpireSolution(false);}
   if(phase=="prepare"){
    var preparationErrors=components.SelectMany(c=>c.RuntimeMessages(GH_RuntimeMessageLevel.Error)).ToArray();
    if(preparationErrors.Length>0)throw new Exception(string.Join(" | ",preparationErrors));
    r["ready"]=components.Where(c=>new[]{"GeometryComponent","MovingBodyComponent"}.Contains(c.GetType().Name)).All(c=>c.Message=="ready");
   }else if(phase=="start"){
    if(index==0){Toggle("Initialize runtime");Toggle("Run");}
    else{var p=owned.Objects.OfType<GH_Panel>().Single(p=>p.NickName=="Recording directory");p.UserText=Path.Combine(output,"recording-32");p.ExpireSolution(false);Toggle("Record");}
    owned.NewSolution(false);
   }else if(phase=="observe"){
    var errors=components.SelectMany(c=>c.RuntimeMessages(GH_RuntimeMessageLevel.Error).Select(e=>c.Name+": "+e)).ToArray();
    if(errors.Length>0)throw new Exception(string.Join(" | ",errors));
    var actor=C(index==0?"Solve":"Record");r["message"]=actor.Message;
    var values=new JsonObject();
    foreach(var c in components)values[c.GetType().Name]=new JsonArray(c.Params.Output.Select(p=>(JsonNode)new JsonObject{["name"]=p.Name,["values"]=new JsonArray(p.VolatileData.AllData(true).Select(v=>JsonValue.Create(v?.ToString())).ToArray())}).ToArray());
    r["outputs"]=values;
    bool passed=false;
    if(index==0){
     var samples=C("Sample").Params.Output[0].VolatileData.AllData(true).OfType<GH_Vector>().ToArray();
     var vectors=C("Vectors").Params.Output[0].VolatileData.AllData(true).OfType<GH_Line>().ToArray();
     var steps=C("Solve").Params.Output[2].VolatileData.AllData(true).OfType<GH_Integer>().ToArray();
     var valid=C("Sample").Params.Output[2].VolatileData.AllData(true).OfType<GH_Boolean>().ToArray();
     r["steps"]=steps.Length==1?steps[0].Value:-1;
     // Solver completion is checked from its status output, not a stale caption.
     var status=C("Solve").Params.Output[1].VolatileData.AllData(true).OfType<GH_String>().Select(v=>v.Value).ToArray();
     passed=status.Contains("completed") && steps.Length==1 && steps[0].Value==60 && valid.Length==3 && valid.All(v=>v.Value) && samples.Length==3 && samples.All(v=>v.Value.IsValid) && vectors.Length==3 && vectors.All(v=>v.Value.IsValid);
    }else{
     var frames=C("Playback").Params.Output[0].VolatileData.AllData(true).Where(v=>v!=null && v.IsValid).ToArray();
     var bodies=C("BodyPreview").Params.Output[0].VolatileData.AllData(true).OfType<GH_Mesh>().ToArray();
     string manifest=Path.Combine(output,"recording-32","manifest.json");
     passed=File.Exists(manifest) && JsonNode.Parse(File.ReadAllText(manifest))["complete"]?.GetValue<bool>()==true && frames.Length==1 && bodies.Length==1 && bodies[0].Value.IsValid && bodies[0].Value.Faces.Count>0;
    }
    r["passed"]=passed;
    if(passed){
     doc.Views.ActiveView.ActiveViewport.ZoomExtents();doc.Views.Redraw();var capture=new Rhino.Display.ViewCapture{Width=1200,Height=800,ScaleScreenItems=true,DrawAxes=false,DrawGrid=false,DrawGridAxes=false};
     using(var bitmap=capture.CaptureToBitmap(doc.Views.ActiveView))bitmap.Save(Path.Combine(output,$"example-{31+index}.png"),System.Drawing.Imaging.ImageFormat.Png);
    }
   }else throw new Exception("Unknown host action");
  }
 }
}catch(Exception e){
 // Retain owned identity even after partial open; close phase disposes it.
 r["error"]=e.ToString();
}
File.WriteAllText(replyPath,r.ToJsonString(new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine(r.ToJsonString());
